$neutrals-white: #ffffff;
$neutrals-gray-200: #e0e0e0;

@mixin tooltip-base {
  display: block;
  padding: 16px 24px;
  position: relative;
  background-color: $neutrals-white;
  border: 1px solid $neutrals-gray-200;
  border-radius: 10px;
  min-width: 100px;
  min-height: 100px;
  max-width: max-content;
  max-height: max-content;
  font-family: "Roboto";
  letter-spacing: 1px;
  gap: 8px;
}

@mixin tooltip-arrow($direction, $position, $offset: 10px, $color: $neutrals-gray-200, $size: 10px, $offset-adjust: 2px) {
  content: "";
  position: absolute;
  @if $direction == top {
    top: -$offset;
    left: $position;
    transform: translateX(-50%);
    border-bottom: $size solid $color;
    border-right: $size solid transparent;
    border-left: $size solid transparent;
  } @else if $direction == bottom {
    bottom: -$offset;
    left: $position;
    transform: translateX(-50%);
    border-top: $size solid $color;
    border-right: $size solid transparent;
    border-left: $size solid transparent;
  } @else if $direction == left {
    left: -$offset;
    top: $position;
    transform: if($position == 50%, translateY(-50%), null);
    border-right: $size solid $color;
    border-top: $size solid transparent;
    border-bottom: $size solid transparent;
  } @else if $direction == right {
    right: -$offset;
    top: $position;
    transform: if($position == 50%, translateY(-50%), null);
    border-left: $size solid $color;
    border-top: $size solid transparent;
    border-bottom: $size solid transparent;
  }
  width: 0;
  height: 0;
}

.tooltip {
  @include tooltip-base;

  &__title {
    line-height: 18.8px;
    font-weight: 600;
  }

  &__content {
    font-size: 14px;
    font-weight: 300;
    line-height: 140%;
    margin: 28px 0;
  }

  &--box-shadow {
    filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.16));
  }

  // Top arrow positions
  &__position--top-center {
    &::before { @include tooltip-arrow(top, 50%, 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(top, 50%, 8px, $neutrals-white, 8px); }
  }

  &__position--top-left {
    &::before { @include tooltip-arrow(top, 10px, 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(top, 12px, 8px, $neutrals-white, 8px); }
  }

  &__position--top-right {
    &::before { @include tooltip-arrow(top, calc(100% - 10px), 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(top, calc(100% - 12px), 8px, $neutrals-white, 8px); }
  }

  // Left arrow positions
  &__position--left-top {
    &::before { @include tooltip-arrow(left, 10px, 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(left, 12px, 8px, $neutrals-white, 8px); }
  }

  &__position--left-center {
    &::before { @include tooltip-arrow(left, 50%, 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(left, 50%, 8px, $neutrals-white, 8px); }
  }

  &__position--left-bottom {
    &::before { @include tooltip-arrow(left, calc(100% - 23px), 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(left, calc(100% - 25px), 8px, $neutrals-white, 8px); }
  }

  // Right arrow positions
  &__position--right-top {
    &::before { @include tooltip-arrow(right, 10px, 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(right, 12px, 8px, $neutrals-white, 8px); }
  }

  &__position--right-center {
    &::before { @include tooltip-arrow(right, 50%, 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(right, 50%, 8px, $neutrals-white, 8px); }
  }

  &__position--right-bottom {
    &::before { @include tooltip-arrow(right, calc(100% - 23px), 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(right, calc(100% - 25px), 8px, $neutrals-white, 8px); }
  }

  // Bottom arrow positions
  &__position--bottom-center {
    &::before { @include tooltip-arrow(bottom, 50%, 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(bottom, 50%, 8px, $neutrals-white, 8px); }
  }

  &__position--bottom-left {
    &::before { @include tooltip-arrow(bottom, 10px, 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(bottom, 12px, 8px, $neutrals-white, 8px); }
  }

  &__position--bottom-right {
    &::before { @include tooltip-arrow(bottom, 90%, 10px, $neutrals-gray-200, 10px); }
    &::after { @include tooltip-arrow(bottom, 90%, 8px, $neutrals-white, 8px); }
  }
}

